import {createHash} from 'node:crypto';import {test,beforeEach} from 'node:test';import assert from 'node:assert/strict';import {readFileSync,readdirSync} from 'node:fs';import {pathToFileURL} from 'node:url';
const base=pathToFileURL(process.env.ADPA_TEST_MODULE_DIR+'/'),lib=await import(new URL('shared-jobs.mjs',base)),api=await import(new URL('shared-jobs-route.mjs',base)),fileApi=await import(new URL('shared-job-evidence-route.mjs',base)),m=await import(new URL('mocks.mjs',base)),coLib=await import(new URL('company.mjs',base)),clLib=await import(new URL('company-clients.mjs',base));
for(const f of readdirSync('drizzle').filter(f=>f.endsWith('.sql')).sort())m.sqlite.exec(readFileSync('drizzle/'+f,'utf8'));
const now='2026-10-10T15:00:00Z',owner={userId:coLib.ADPA_OWNER,email:'owner@example.test'},arman={userId:'arman',email:'arman@example.test'},ana={userId:'ana',email:'ana@example.test'},home={userId:'home',email:'home@example.test'},tech={userId:'tech',email:'tech@example.test'},other={userId:'other',email:'other@example.test'};let jobId;
const contact={name:'Synthetic Homeowner',email:home.email,address:'Synthetic Property',phone:'',service:'Water extraction',referral:'',contactBasis:'Synthetic request',smsConsent:'Not recorded',smsBasis:'',emailAllowed:true};
function company(id,actor,type){const s=coLib.companyState({serviceType:type,directoryListed:true,members:[{id:actor.userId,name:actor.userId,email:actor.email,userId:actor.userId,role:'Manager',acceptedAt:now,revoked:false},{id:'tech',name:'Crew',email:tech.email,userId:tech.userId,role:'Technician',acceptedAt:now,revoked:false}]});m.sqlite.prepare('INSERT INTO companies VALUES (?,?,?,?,1,?,?)').run(id,owner.userId,'Synthetic '+id,JSON.stringify(s),now,now);}
function asset(id,cid,clid,kind='Client document'){const bytes=new TextEncoder().encode('%PDF-synthetic-'+id).buffer;m.storage.set('original/'+id,{size:bytes.byteLength,body:new Uint8Array(bytes),async arrayBuffer(){return bytes;}});m.sqlite.prepare('INSERT INTO company_assets VALUES (?,?,?,?,?,?,?,?,?,?,?,?)').run(id,cid,clid,kind,'Synthetic '+id,'1',id+'.pdf','application/pdf',bytes.byteLength,'original/'+id,createHash('sha256').update(new Uint8Array(bytes)).digest('hex'),now);}
function client(id,cid,changes={}){const s={...clLib.newClient(contact,now),contract:{status:'Completed',requestId:id+'-request',verifiedAt:now,signedAssetId:id+'-signed',certificateAssetId:id+'-certificate'},...changes};m.sqlite.prepare('INSERT INTO company_clients VALUES (?,?,?,1,?,?)').run(id,cid,JSON.stringify(s),now,now);asset(id+'-signed',cid,id,'Signed contract');asset(id+'-certificate',cid,id,'Signature certificate');}
function row(){return m.sqlite.prepare('SELECT * FROM shared_jobs WHERE id=?').get(jobId);}function state(){return JSON.parse(row().state);}const get=id=>api.GET(new Request('https://claims.test/api/shared-jobs'+(id?'?id='+id:'')));
const post=body=>api.POST(new Request('https://claims.test/api/shared-jobs'+(jobId?'?id='+jobId:''),{method:'POST',headers:{origin:'https://claims.test','Content-Type':'application/json'},body:JSON.stringify({...body,...(jobId?{version:row().version}:{}),...('version' in body?{version:body.version}:{})})}));
const file=(id,extra='')=>fileApi.GET(new Request('https://claims.test/api/shared-job-evidence?jobId='+jobId+'&id='+id+extra));
async function begin(){m.setUser(arman);const r=await post({action:'create',companyId:'water',companyVersion:1,clientId:'water-client',clientVersion:1});assert.equal(r.status,201,await r.clone().text());jobId=(await r.json()).id;}
async function accept(){m.setUser(home);assert.equal((await post({action:'acceptHomeowner',consent:true})).status,200);}
async function joinAna(){m.setUser(arman);assert.equal((await post({action:'inviteCompany',companyId:'contents'})).status,200);m.setUser(ana);assert.equal((await post({action:'acceptCompany',companyId:'contents',companyVersion:1,clientId:'contents-client',clientVersion:1,termsConfirmed:true})).status,200);m.setUser(home);assert.equal((await post({action:'approveCompany',companyId:'contents',consent:true})).status,200);}
async function contribute(){m.setUser(arman);const r=await post({action:'contribute',companyId:'water',companyVersion:1,assetId:'damage',category:'Damage photos',description:'Synthetic damaged kitchen evidence',noSensitiveData:true});assert.equal(r.status,200,await r.clone().text());return state().evidence.at(-1).id;}
function claim(id='claim',address=contact.address){const s={authority:{controls:{engagementFileId:'engagement'}}};m.sqlite.prepare('INSERT INTO claims VALUES (?,?,?,?,?,1,?,?)').run(id,owner.userId,contact.name,address,JSON.stringify(s),now,now);m.sqlite.prepare('INSERT INTO evidence VALUES (?,?,?,?,?,?,?,?,?,?,?)').run('engagement',id,owner.userId,'engagement.pdf','application/pdf',10,'Policy and representation','Synthetic agreement','[]','agreement',now);m.storage.set('agreement',{size:10,body:new TextEncoder().encode('%PDF-test')});}
async function connect(){m.setUser(home);await post({action:'requestADPA',consent:true});claim();m.setUser(owner);const r=await post({action:'linkADPA',claimId:'claim',claimVersion:1,engagementFileId:'engagement',reviewed:true});assert.equal(r.status,200,await r.clone().text());m.setUser(home);assert.equal((await file('', '&engagement=1')).status,200);assert.equal((await post({action:'confirmADPA',consent:true})).status,200);}
beforeEach(()=>{m.sqlite.exec('DELETE FROM shared_job_companies;DELETE FROM shared_jobs;DELETE FROM company_assets;DELETE FROM company_clients;DELETE FROM evidence;DELETE FROM claims;DELETE FROM companies;');m.storage.clear();jobId=null;m.setUser(arman);company('water',arman,'Water mitigation');company('contents',ana,'Contents care');client('water-client','water');client('contents-client','contents');asset('damage','water','water-client');asset('unrelated','water','other-client');});
test('company creates a pre-ADPA recovery job with no implicit homeowner or ADPA grant',async()=>{await begin();assert.equal(state().adpa.status,'Not requested');m.setUser(home);const v=await (await get(jobId)).json();assert.equal(v.needsHomeownerAcceptance,true);m.setUser(owner);assert.equal((await get(jobId)).status,404);m.setUser(other);assert.equal((await get(jobId)).status,404);m.setUser(tech);assert.equal((await get(jobId)).status,404);});
test('only exact invited homeowner accepts, and verified originating contract is required',async()=>{await begin();m.setUser(arman);assert.equal((await post({action:'acceptHomeowner',consent:true})).status,400);m.setUser(home);m.sqlite.prepare('DELETE FROM company_assets WHERE id=?').run('water-client-certificate');assert.equal((await post({action:'acceptHomeowner',consent:true})).status,400);asset('water-client-certificate','water','water-client','Signature certificate');await accept();assert.equal(state().homeowner.userId,home.userId);assert.ok(state().companies[0].approvedAt);assert.equal((await post({action:'acceptHomeowner',consent:true})).status,400);m.setUser({...home,userId:'wrong-user'});assert.equal((await get(jobId)).status,404);});
test('company invitation, own signed agreement and homeowner approval are separate gates',async()=>{await begin();await accept();const e=await contribute();await post({action:'inviteCompany',companyId:'contents'});m.setUser(ana);let v=await (await get(jobId)).json();assert.deepEqual(v.evidence,[]);assert.deepEqual(v.companies,[]);m.sqlite.prepare("UPDATE company_clients SET state=json_set(state,'$.contract.status','Sent') WHERE id='contents-client'").run();assert.equal((await post({action:'acceptCompany',companyId:'contents',companyVersion:1,clientId:'contents-client',clientVersion:1,termsConfirmed:true})).status,400);m.sqlite.prepare("UPDATE company_clients SET state=json_set(state,'$.contract.status','Completed') WHERE id='contents-client'").run();assert.equal((await post({action:'acceptCompany',companyId:'contents',companyVersion:1,clientId:'contents-client',clientVersion:1,termsConfirmed:true})).status,200);assert.equal((await file(e)).status,404);m.setUser(home);await post({action:'approveCompany',companyId:'contents',consent:true});m.setUser(ana);assert.equal((await file(e)).status,404);});
test('homeowner grants precise evidence reuse and changes revoke subsequent downloads',async()=>{await begin();await accept();await joinAna();const e=await contribute();m.setUser(ana);assert.equal((await file(e)).status,404);assert.equal((await post({action:'share',evidenceId:e,companyIds:['contents'],includeADPA:false,consent:true})).status,400);m.setUser(home);assert.equal((await post({action:'share',evidenceId:e,companyIds:['contents'],includeADPA:false,consent:true})).status,200);m.setUser(ana);const r=await file(e);assert.equal(r.status,200);assert.equal(r.headers.get('Cache-Control'),'private, no-store');assert.match(r.headers.get('Content-Disposition'),/^attachment/);assert.match(await r.text(),/synthetic-damage/);const v=await (await get(jobId)).json();assert.equal(v.evidence[0].digest,createHash('sha256').update('%PDF-synthetic-damage').digest('hex'));assert.equal(v.evidence[0].companyName,'Synthetic water');assert.ok(!JSON.stringify(v).includes('original/damage'));m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:false,consent:true});m.setUser(ana);assert.equal((await file(e)).status,404);});
test('other client files, contract PDFs and unknown company recipients cannot be contributed/shared',async()=>{await begin();await accept();m.setUser(arman);for(const assetId of ['unrelated','water-client-signed','contents-client-signed'])assert.equal((await post({action:'contribute',companyId:'water',companyVersion:1,assetId,category:'Damage photos',description:'Synthetic',noSensitiveData:true})).status,400);const e=await contribute();m.setUser(home);assert.equal((await post({action:'share',evidenceId:e,companyIds:['not-in-job'],includeADPA:false,consent:true})).status,400);assert.equal((await post({action:'share',evidenceId:e,companyIds:[],includeADPA:true,consent:true})).status,400);});
test('company removal and member revocation immediately block job access and downloads',async()=>{await begin();await accept();await joinAna();const e=await contribute();m.setUser(home);await post({action:'share',evidenceId:e,companyIds:['contents'],includeADPA:false,consent:true});await post({action:'removeCompany',companyId:'contents',reason:'Synthetic removal'});m.setUser(ana);assert.equal((await get(jobId)).status,404);assert.equal((await file(e)).status,404);m.setUser(arman);m.sqlite.prepare("UPDATE companies SET state=json_set(state,'$.members[0].revoked',1),version=2 WHERE id='water'").run();assert.equal((await get(jobId)).status,404);assert.equal((await file(e)).status,404);});
test('tasks remain within own approved company and updates use optimistic version guards',async()=>{await begin();await accept();await joinAna();m.setUser(arman);assert.equal((await post({action:'task',companyId:'water',companyVersion:1,title:'Drying check',due:'2026-10-12',note:'Take room readings'})).status,200);const t=state().tasks[0];m.setUser(ana);assert.equal((await post({action:'completeTask',companyId:'water',companyVersion:1,taskId:t.id,note:'Fake complete'})).status,404);assert.equal((await post({action:'task',companyId:'contents',companyVersion:1,title:'Pack out',due:'2026-02-30',note:'Plan'})).status,400);m.setUser(arman);assert.equal((await post({action:'completeTask',version:1,companyId:'water',companyVersion:1,taskId:t.id,note:'Done'})).status,409);assert.equal((await post({action:'completeTask',companyId:'water',companyVersion:1,taskId:t.id,note:'Readings completed'})).status,200);});
test('ADPA cannot inspect or import job evidence until separate representation and homeowner grant',async()=>{await begin();await accept();const e=await contribute();m.setUser(home);await post({action:'requestADPA',consent:true});m.setUser(owner);assert.equal((await get(jobId)).status,200);assert.equal((await file(e)).status,404);assert.equal((await post({action:'importEvidence',evidenceId:e})).status,403);claim('claim','Wrong address');assert.equal((await post({action:'linkADPA',claimId:'claim',claimVersion:1,engagementFileId:'engagement',reviewed:true})).status,400);m.sqlite.prepare('UPDATE claims SET address=? WHERE id=?').run(contact.address,'claim');assert.equal((await post({action:'linkADPA',claimId:'claim',claimVersion:1,engagementFileId:'engagement',reviewed:true})).status,200);m.setUser(arman);assert.equal((await file('', '&engagement=1')).status,404);m.setUser(home);await post({action:'confirmADPA',consent:true});m.setUser(owner);assert.equal((await file(e)).status,404);assert.equal((await post({action:'importEvidence',evidenceId:e})).status,400);m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:true,consent:true});m.setUser(owner);assert.equal((await file(e)).status,200);const r=await post({action:'importEvidence',evidenceId:e});assert.equal(r.status,200,await r.clone().text());const id=(await r.json()).evidenceId,original=m.sqlite.prepare('SELECT * FROM evidence WHERE id=?').get(id);assert.equal(original.claim_id,'claim');assert.match(original.object_key,/\/shared\//);assert.notEqual(original.object_key,'original/damage');assert.ok(m.storage.has(original.object_key));assert.equal(JSON.parse(original.sources)[0].originalDigest,createHash('sha256').update('%PDF-synthetic-damage').digest('hex'));assert.equal((await post({action:'importEvidence',evidenceId:e})).status,200);assert.equal(m.sqlite.prepare('SELECT COUNT(*) n FROM evidence WHERE id=?').get(id).n,1);m.setUser(home);await post({action:'removeADPA',reason:'Withdraw app collaboration'});m.setUser(owner);assert.equal((await get(jobId)).status,404);assert.equal((await file(e)).status,404);assert.ok(m.sqlite.prepare('SELECT id FROM evidence WHERE id=?').get(id));});
test('changed engagement and withdrawn evidence block new imports',async()=>{await begin();await accept();const e=await contribute();await connect();m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:true,consent:true});m.setUser(owner);m.sqlite.prepare("UPDATE claims SET state=json_set(state,'$.authority.controls.engagementFileId','other') WHERE id='claim'").run();assert.equal((await post({action:'importEvidence',evidenceId:e})).status,400);m.setUser(home);await post({action:'withdrawEvidence',evidenceId:e,reason:'Wrong photo'});assert.equal((await file(e)).status,404);});
test('registration assigns only signed-in manager and directory excludes contact and client records',async()=>{m.setUser(other);let r=await post({action:'registerCompany',name:'Synthetic Roofer',serviceType:'Roofing',termsConfirmed:true});assert.equal(r.status,201);const id=(await r.json()).companyId,c=m.sqlite.prepare('SELECT * FROM companies WHERE id=?').get(id),s=JSON.parse(c.state);assert.equal(s.members[0].userId,other.userId);assert.equal(s.members[0].email,other.email);assert.equal(s.directoryListed,false);assert.equal((await post({action:'registerCompany',name:'Fake',serviceType:'Roofing',termsConfirmed:true,managerEmail:arman.email})).status,400);r=await post({action:'directoryListing',companyId:id,companyVersion:1,listed:true,consent:true});assert.equal(r.status,200);m.setUser(home);const d=await (await get()).json();const listing=d.directory.find(c=>c.id===id);assert.deepEqual(Object.keys(listing).sort(),['id','name','primaryIndustry','serviceType']);assert.equal(listing.primaryIndustry,'Roofing');assert.deepEqual(d.companies,[]);assert.deepEqual(d.jobs,[]);});
test('auth, request origin, duplicate create, stale client and invitation directory checks',async()=>{m.setUser(null);assert.equal((await get()).status,401);m.setUser(arman);assert.equal((await api.POST(new Request('https://claims.test/api/shared-jobs',{method:'POST',headers:{origin:'https://evil.test'},body:'{}'}))).status,403);assert.equal((await post({action:'create',companyId:'water',companyVersion:1,clientId:'contents-client',clientVersion:1})).status,404);assert.equal((await post({action:'create',companyId:'water',companyVersion:1,clientId:'water-client',clientVersion:5})).status,409);await begin();const previous=jobId;jobId=null;assert.equal((await post({action:'create',companyId:'water',companyVersion:1,clientId:'water-client',clientVersion:1})).status,409);jobId=previous;await accept();m.sqlite.prepare("UPDATE companies SET state=json_set(state,'$.directoryListed',0) WHERE id='contents'").run();assert.equal((await post({action:'inviteCompany',companyId:'contents'})).status,400);});
test('source digest changes or company archival invalidate original downloads',async()=>{await begin();await accept();const e=await contribute();m.setUser(home);m.sqlite.prepare("UPDATE company_assets SET digest='changed' WHERE id='damage'").run();assert.equal((await file(e)).status,404);m.sqlite.prepare("UPDATE company_assets SET digest=? WHERE id='damage'").run(createHash('sha256').update('%PDF-synthetic-damage').digest('hex'));m.sqlite.prepare("UPDATE companies SET state=json_set(state,'$.archived',1) WHERE id='water'").run();assert.equal((await file(e)).status,404);});
test('portfolio cursor paginates without duplicates and directory search remains bounded across 1000 companies',async()=>{m.setUser(home);for(let n=0;n<125;n++){const id='page-'+String(n).padStart(3,'0'),cid='page-client-'+n,s=clLib.newClient({...contact,name:'Synthetic '+n},now);m.sqlite.prepare('INSERT INTO company_clients VALUES (?,?,?,1,?,?)').run(cid,'water',JSON.stringify(s),now,now);const j=lib.createShared({id:'water',name:'Water',state:{serviceType:'Water mitigation'}},{id:cid,state:s},now,arman);m.sqlite.prepare('INSERT INTO shared_jobs (id,creator_company_id,origin_client_id,homeowner_email,name,address,state,version,created,updated) VALUES (?,?,?,?,?,?,?,1,?,?)').run(id,'water',cid,home.email,j.name,j.address,JSON.stringify(j.state),now,now);m.sqlite.prepare('INSERT INTO shared_job_companies VALUES (?,?,?)').run(id+':water',id,'water');}let d=await (await get()).json();assert.equal(d.jobs.length,100);assert.equal(d.hasMore,true);const c=d.nextCursor,next=await (await api.GET(new Request('https://claims.test/api/shared-jobs?cursorUpdated='+encodeURIComponent(c.updated)+'&cursorId='+encodeURIComponent(c.id)))).json();assert.equal(next.jobs.length,25);assert.equal(next.hasMore,false);assert.equal(new Set([...d.jobs,...next.jobs].map(j=>j.id)).size,125);for(let n=0;n<1000;n++){m.sqlite.prepare('INSERT INTO companies VALUES (?,?,?,?,1,?,?)').run('roof-'+n,owner.userId,'Synthetic Roofer '+String(n).padStart(4,'0'),JSON.stringify(coLib.companyState({serviceType:'Roofing',directoryListed:true})),now,now);}d=await (await get()).json();assert.equal(d.directory.length,100);assert.equal(d.directoryHasMore,true);const search=await (await api.GET(new Request('https://claims.test/api/shared-jobs?search=Synthetic%20Roofer%200999'))).json();assert.equal(search.directory.length,1);assert.equal(search.directory[0].id,'roof-999');m.setUser(other);assert.equal((await (await get()).json()).jobs.length,0);});
test('source bytes with a false stored digest never enter the ADPA claim',async()=>{await begin();await accept();const e=await contribute();await connect();m.setUser(home);await post({action:'share',evidenceId:e,companyIds:[],includeADPA:true,consent:true});m.storage.set('original/damage',{size:8,body:new TextEncoder().encode('changed'),async arrayBuffer(){return new TextEncoder().encode('changed').buffer;}});m.setUser(owner);assert.equal((await post({action:'importEvidence',evidenceId:e})).status,400);assert.equal(m.sqlite.prepare("SELECT COUNT(*) n FROM evidence WHERE category='Shared job evidence'").get().n,0);});

test('policyholder and assigned companies exchange scoped messages without leaking other company conversations',async()=>{
 await begin();await accept();await joinAna();m.setUser(home);
 assert.equal((await post({action:'jobMessage',audience:'company:water',body:'Private water question'})).status,200);
 assert.equal((await post({action:'jobMessage',audience:'team',body:'Everyone update'})).status,200);
 m.setUser(arman);let v=await (await get(jobId)).json();assert.deepEqual(v.messages.map(x=>x.body),['Private water question','Everyone update']);
 assert.equal((await post({action:'jobMessage',companyId:'water',companyVersion:1,audience:'company:water',body:'Water reply'})).status,200);
 m.setUser(ana);v=await (await get(jobId)).json();assert.deepEqual(v.messages.map(x=>x.body),['Everyone update']);assert.ok(!JSON.stringify(v).includes('Private water question'));
 assert.equal((await post({action:'jobMessage',companyId:'contents',companyVersion:1,audience:'company:water',body:'Unauthorized'})).status,400);
 assert.equal((await post({action:'jobMessage',audience:'team',body:'Spoofed sender'})).status,400);
 m.setUser(home);assert.equal((await post({action:'jobMessage',audience:'adpa',body:'Not connected'})).status,400);
 await post({action:'removeCompany',companyId:'contents',reason:'Removed'});m.setUser(ana);assert.equal((await get(jobId)).status,404);
});
